  await E(()=>{ BT.ssel=BT.sks.findIndex(k=>k.name==='ブレイズエッジ'); pressA(); }); for(let i=0;i<40;i++){ await W(100); if(await E(()=>BT&&BT.phase==='menu')||await E(()=>!BT)) break; }
  T('ブレイズエッジで MPが 減る', await E(()=>STATS.elt.mp===17));
