  T('2体まで（1人）', await E(()=>{ const sb=window.startBattle; let mx=0; window.startBattle=(d)=>{ mx=Math.max(mx,d.length); }; for(let i=0;i<500;i++) startEnc('west'); window.startBattle=sb; return mx===2; }));
  T('全滅すると 町へ', await (async()=>{ await E(()=>{ STATS.elt.hp=1; STATS.elt.defT=0; BAG.gold=100; enterWorld([22.5,31.5]); startBattle([FOES.ishikurage]); }); await waitMenu(); await E(()=>{ BT.sel=CMDS.indexOf('ぼうぎょ'); pressA(); }); for(let i=0;i<120;i++){ await W(100); if(await E(()=>{ if(BT&&BT.waitA) pressA(); return !BT; })) break; } await W(800); return E(()=>cur.kind==='town'&&BAG.gold===50&&STATS.elt.hp===STATS.elt.max); })());
