  T('セーブして 再開しても 村は 燃えた まま（ガイルの 別れの 後）', await (async()=>{ await E(()=>{ ST.phase='road'; enterTown([12,10],'rue'); saveGame(); }); await pg.reload({waitUntil:'load'}); for(let i=0;i<60;i++){ await W(150); if(await E(()=>typeof MENU!=='undefined' && !!MENU)) break; } await E(()=>{ MENU.sel=0; pressA(); if(MENU && /どの きろく/.test(MENU.title)){ MENU.sel=0; pressA(); } window.FX_FAST=1; }); await W(1000); return E(()=>ST.phase==='road' && TOWN_NOW==='rue' && fireMeshes.length>0 && S.background.getHex()===0x1a0f18); })());
